#include <iostream>
#include <string>
using namespace std;

class Coffee {
public:
    virtual double cost() = 0;
    virtual string description() = 0;
    virtual ~Coffee() {}
};

class SimpleCoffee : public Coffee {
public:
    double cost() override { return 2.0; }
    string description() override { return "Coffee"; }
};

class MilkDecorator : public Coffee {
    Coffee& wrapped;
public:
    MilkDecorator(Coffee& c) : wrapped(c) {}
    double cost() override { return wrapped.cost() + 0.5; }
    string description() override { return wrapped.description() + " + Milk"; }
};

class SugarDecorator : public Coffee {
    Coffee& wrapped;
public:
    SugarDecorator(Coffee& c) : wrapped(c) {}
    double cost() override { return wrapped.cost() + 0.25; }
    string description() override { return wrapped.description() + " + Sugar"; }
};

int main() {
    SimpleCoffee coffee;
    MilkDecorator withMilk(coffee);
    SugarDecorator withSugar(withMilk);
    cout << withSugar.description() << " : $" << withSugar.cost() << endl;
    return 0;
}
